} from './messages.js';

describe('WebSocket message types', () => {
  it('keeps existing messages assignable and types session list frames', () => {
    const existingIncoming: IncomingMessage = {type: 'user_message', content: 'hello'};
    const listRequest: IncomingMessage = {type: 'list_sessions', limit: 10} satisfies ListSessionsMessage;
    const existingOutgoing: OutgoingMessage = {
      type: 'connected',
      sessionId: 's1',
      message: 'ready',
      examplePrompts: [],
    } satisfies ConnectedMessage;
    const summary: SessionSummaryFrame = {
      sessionId: 's1',
      createdAt: '2026-01-01T00:00:00.000Z',
      updatedAt: '2026-01-02T00:00:00.000Z',
      entryCount: 2,
    };
    const listed: OutgoingMessage = {type: 'session_list', sessions: [summary]} satisfies SessionListMessage;

    expect(existingIncoming.type).toBe('user_message');
    expect(listRequest.type).toBe('list_sessions');
